const http=require('node:http');const server=http.createServer((req,res)=>{const u=new URL(req.url,'http://localhost');res.setHeader('content-type','application/json');if(u.pathname==='/health'){res.end(JSON.stringify({ready:true}));return;}if(u.pathname==='/sum'){const a=Number(u.searchParams.get('a')),b=Number(u.searchParams.get('b'));res.end(JSON.stringify({result:a-b}));return;}res.statusCode=404;res.end(JSON.stringify({error:'not found'}));});server.listen(0,'127.0.0.1',()=>console.log(JSON.stringify({port:server.address().port})));process.on('SIGTERM',()=>server.close(()=>process.exit(0)));
